<?php
require_once __DIR__.'/includes/functions.php';$slug=trim($_GET['slug']??'');$s=db()->prepare("SELECT n.*,c.name category,c.slug category_slug,u.name author FROM news n LEFT JOIN categories c ON c.id=n.category_id LEFT JOIN users u ON u.id=n.user_id WHERE n.slug=? AND n.status='published' AND n.deleted_at IS NULL LIMIT 1");$s->execute([$slug]);$a=$s->fetch();if(!$a){http_response_code(404);$pageTitle='الخبر غير موجود';require __DIR__.'/includes/header.php';echo '<div class="container py-5"><div class="panel p-5 text-center"><h1>404</h1><p>الخبر المطلوب غير موجود أو غير منشور.</p><a class="btn btn-primary" href="'.url().'">العودة للرئيسية</a></div></div>';require __DIR__.'/includes/footer.php';exit;}db()->prepare('UPDATE news SET views_count=views_count+1 WHERE id=?')->execute([$a['id']]);$a['views_count']++;$s=db()->prepare("SELECT title,slug,image FROM news WHERE category_id=? AND id<>? AND status='published' AND deleted_at IS NULL ORDER BY published_at DESC LIMIT 3");$s->execute([$a['category_id'],$a['id']]);$related=$s->fetchAll();$pageTitle=$a['seo_title']?:$a['title'];$metaDescription=$a['seo_description']?:$a['summary'];require __DIR__.'/includes/header.php';?><article class="container py-5"><div class="row justify-content-center"><div class="col-xl-9"><a class="category-badge" href="<?=url('category.php?slug='.rawurlencode($a['category_slug']))?>"><?=e($a['category'])?></a><h1 class="display-5 fw-bold my-4"><?=e($a['title'])?></h1><p class="lead text-secondary"><?=e($a['summary'])?></p><div class="article-meta mb-4"><span><i class="bi bi-person"></i> <?=e($a['author'])?></span> · <span><i class="bi bi-calendar3"></i> <?=formatDate($a['published_at'])?></span> · <span><i class="bi bi-eye"></i> <?=$a['views_count']?></span></div><img class="w-100 rounded-4 shadow-sm mb-5" style="max-height:570px;object-fit:cover" src="<?=imageUrl($a['image'])?>" alt="<?=e($a['title'])?>"><div class="article-body panel p-4 p-lg-5"><?=sanitizeHtml($a['details'])?></div><div class="mt-4 d-flex align-items-center gap-2"><strong>مشاركة:</strong><a class="btn btn-outline-primary btn-sm" target="_blank" href="https://www.facebook.com/sharer/sharer.php?u=<?=urlencode('http://'.($_SERVER['HTTP_HOST']??'localhost').$_SERVER['REQUEST_URI'])?>"><i class="bi bi-facebook"></i></a><a class="btn btn-outline-primary btn-sm" target="_blank" href="https://twitter.com/intent/tweet?text=<?=urlencode($a['title'])?>"><i class="bi bi-twitter-x"></i></a><a class="btn btn-outline-success btn-sm" target="_blank" href="https://wa.me/?text=<?=urlencode($a['title'])?>"><i class="bi bi-whatsapp"></i></a></div><?php if($related):?><h2 class="section-title mt-5">أخبار ذات صلة</h2><div class="row g-4"><?php foreach($related as $r):?><div class="col-md-4"><a class="news-card d-block text-decoration-none text-dark" href="<?=url('news.php?slug='.rawurlencode($r['slug']))?>"><img src="<?=imageUrl($r['image'])?>"><strong class="d-block p-3"><?=e($r['title'])?></strong></a></div><?php endforeach;?></div><?php endif;?></div></div></article><?php require __DIR__.'/includes/footer.php';?>
